export default function next({ rows, previous, sheet }) {
  const header = rows[0] ?? [],
    index = previous?.index ?? 1,
    domainCol = header.indexOf("Domain");
  if (domainCol < 0) throw Error("Missing Domain header");
  const required = ["Market", "Industry", "Value Proposition", "Target Audience"],
    cols = required.map((n) => header.indexOf(n));
  if (cols.some((n) => n < 0)) throw Error("Missing output column");
  if (index >= rows.length)
    return {
      more: false,
      state: { index },
      domain: "",
      url: "https://example.test",
      row: index + 1,
      columns: cols,
      sheet,
    };
  const domain = String(rows[index][domainCol] ?? "");
  if (!domain) throw Error("Empty domain");
  return {
    more: true,
    state: { index: index + 1 },
    domain,
    url: "https://www." + domain,
    row: index + 1,
    columns: cols,
    sheet,
  };
}

