export default function prompt({ domain, content }) {
  return {
    input: `This is the content of the website ${domain}: "${content}"\n\nIn JSON provide value_proposition (under 25 English words, casual, formatted "[Company Name] helps [target audience] [achieve desired outcome] and [additional benefit]"), industry (choose Agriculture, Arts, Construction, Consumer Goods, Education, Entertainment, Finance, Other, Health Care, Legal, Manufacturing, Media & Communications, Public Administration, Advertisements, Real Estate, Recreation & Travel, Retail, Software, Transportation & Logistics, Wellness & Fitness; prefer Consumer Goods when ambiguous with Software), target_audience (choose lowercase sales teams, marketing teams, hr teams, customer service teams, consumers, c-levels), and market (B2B or B2C).`,
  };
}

