export default function result({ response, row, columns, sheet }) {
  const raw =
    response.output_text ??
    response.output?.flatMap((x) => x.content ?? []).find((x) => x.type === "output_text")?.text;
  if (response.status && response.status !== "completed") throw Error("OpenAI response incomplete");
  const data = JSON.parse(raw);
  const fields = [data.market, data.industry, data.value_proposition, data.target_audience];
  if (fields.some((x) => typeof x !== "string")) throw Error("Missing classification field");
  const col = (n) => {
    let x = n + 1,
      s = "";
    while (x) {
      x--;
      s = String.fromCharCode(65 + (x % 26)) + s;
      x = Math.floor(x / 26);
    }
    return s;
  };
  const quoted = "'" + sheet.replace(/'/g, "''") + "'!";
  return Object.fromEntries(
    fields.flatMap((v, i) => [
      ["range" + i, quoted + col(columns[i]) + row],
      ["values" + i, [[v]]],
    ]),
  );
}
